# ruff: noqa: F821
# graph_headroom — evolution seed for the dev-continuum-* family.  Identity stays
# outside EVOLVE-BLOCKs; Shinka operators may change only the implementation below.
#
# Why this seed and not `least_allocated` (the dev-medium-hot seed): on this family the
# dependency-blind policies are *infeasible* (worst SLO 0.88 against a 0.90 target), so
# seeding from one would start every arm outside the feasible region and turn the first
# half of every campaign into a feasibility hunt rather than a search.  This seed is the
# most SLO-margined feasible hand-written policy (0.95); it is also the *expensive* one
# (1.27 normalized energy against `latency_greedy`'s 0.83), which is deliberate — the
# search starts feasible and has an explicit, large energy gap to close rather than
# starting at the best baseline with nowhere to go.
POLICY_NAME: str = "graph_headroom"
POLICY_VERSION: str = "1.0.0"

# EVOLVE-BLOCK-START
def graph_latency_ctx(pod: Pod, node: NodeState, ctx: ClusterCtx) -> float:
    latency_sum = 0.0
    rate_sum = 0.0
    for i in range(len(ctx.graph.src)):
        src = ctx.graph.src[i]
        dst = ctx.graph.dst[i]
        rate = ctx.graph.rate[i]
        other = -1
        if src == pod.id:
            other = dst
        elif dst == pod.id:
            other = src
        if other >= 0 and other != pod.id:
            neighbor = ctx.pods[other]
            if neighbor.current_node >= 0:
                latency = node.latency_to_ms[neighbor.current_node]
                latency_sum += latency * rate
                rate_sum += rate
    if rate_sum > 0.0:
        return latency_sum / rate_sum
    return 0.0

def graph_latency_state(pod: Pod, node: NodeState, state: ClusterState, graph: CallGraphCtx) -> float:
    latency_sum = 0.0
    rate_sum = 0.0
    for i in range(len(graph.src)):
        src = graph.src[i]
        dst = graph.dst[i]
        rate = graph.rate[i]
        other = -1
        if src == pod.id:
            other = dst
        elif dst == pod.id:
            other = src
        if other >= 0 and other != pod.id:
            neighbor = state.pods[other]
            if neighbor.current_node >= 0:
                latency = node.latency_to_ms[neighbor.current_node]
                latency_sum += latency * rate
                rate_sum += rate
    if rate_sum > 0.0:
        return latency_sum / rate_sum
    return 0.0

def score(pod: Pod, node: NodeState, ctx: ClusterCtx) -> float:
    if node.suspended:
        return -1000000.0
    if node.cpu_allocated + pod.cpu_request > node.cpu_capacity:
        return -1000000.0
    if node.mem_allocated + pod.mem_request > node.mem_capacity:
        return -1000000.0
    cpu_before = 0.0
    if node.cpu_capacity > 0:
        cpu_before = float(node.cpu_allocated) / float(node.cpu_capacity)
    cpu_after = 0.0
    if node.cpu_capacity > 0:
        cpu_after = float(node.cpu_allocated + pod.cpu_request) / float(node.cpu_capacity)
    mem_after = 0.0
    if node.mem_capacity > 0:
        mem_after = float(node.mem_allocated + pod.mem_request) / float(node.mem_capacity)
    delta_cpu = cpu_after - cpu_before
    dynamic_power = (node.power_max_w - node.power_idle_w) * delta_cpu
    idle_penalty = 0.0
    if node.cpu_allocated == 0 and node.mem_allocated == 0 and node.suspendable:
        idle_penalty = node.power_idle_w
    marginal_power = idle_penalty + dynamic_power
    avg_latency = graph_latency_ctx(pod, node, ctx)
    cpu_pressure = cpu_after * cpu_after
    mem_pressure = mem_after * mem_after
    result = - avg_latency * 5.0 - marginal_power * 0.25 - cpu_pressure * 150.0 - mem_pressure * 75.0
    if node.cpu_allocated > 0 or node.mem_allocated > 0:
        result += 20.0
    return result

def pod_node_score_state(pod: Pod, node: NodeState, state: ClusterState, graph: CallGraphCtx) -> float:
    if node.suspended:
        return -1000000.0
    if node.cpu_allocated + pod.cpu_request > node.cpu_capacity:
        return -1000000.0
    if node.mem_allocated + pod.mem_request > node.mem_capacity:
        return -1000000.0
    cpu_before = 0.0
    if node.cpu_capacity > 0:
        cpu_before = float(node.cpu_allocated) / float(node.cpu_capacity)
    cpu_after = 0.0
    if node.cpu_capacity > 0:
        cpu_after = float(node.cpu_allocated + pod.cpu_request) / float(node.cpu_capacity)
    mem_after = 0.0
    if node.mem_capacity > 0:
        mem_after = float(node.mem_allocated + pod.mem_request) / float(node.mem_capacity)
    delta_cpu = cpu_after - cpu_before
    dynamic_power = (node.power_max_w - node.power_idle_w) * delta_cpu
    idle_penalty = 0.0
    if node.cpu_allocated == 0 and node.mem_allocated == 0 and node.suspendable:
        idle_penalty = node.power_idle_w
    marginal_power = idle_penalty + dynamic_power
    avg_latency = graph_latency_state(pod, node, state, graph)
    cpu_pressure = cpu_after * cpu_after
    mem_pressure = mem_after * mem_after
    result = - avg_latency * 5.0 - marginal_power * 0.25 - cpu_pressure * 150.0 - mem_pressure * 75.0
    if node.cpu_allocated > 0 or node.mem_allocated > 0:
        result += 20.0
    return result

def propose_moves(state: ClusterState, graph: CallGraphCtx, budget: int) -> list[Move]:
    out: list[Move] = []
    for pod in state.pods:
        if len(out) >= budget:
            return out
        if pod.current_node >= 0:
            current_node = state.nodes[pod.current_node]
            current_score = pod_node_score_state(pod, current_node, state, graph)
            best_node = -1
            best_score = current_score
            for i in range(len(state.nodes)):
                if i != pod.current_node:
                    node = state.nodes[i]
                    fits = node.cpu_allocated + pod.cpu_request <= node.cpu_capacity and node.mem_allocated + pod.mem_request <= node.mem_capacity
                    if fits:
                        score_val = pod_node_score_state(pod, node, state, graph)
                        if score_val > best_score:
                            best_score = score_val
                            best_node = i
            if best_node >= 0:
                improvement = best_score - current_score
                if current_node.cpu_allocated == pod.cpu_request and current_node.mem_allocated == pod.mem_request:
                    if current_node.suspendable:
                        improvement += current_node.power_idle_w * 1.0
                threshold = 10.0
                if pod.stateful or pod.has_pdb:
                    threshold = 50.0
                if pod.image_mb > 100:
                    threshold += float(pod.image_mb) * 0.1
                if improvement > threshold:
                    out.append(move_pod(pod.id, best_node))
    return out
# EVOLVE-BLOCK-END
